def min_window_substring(s, t):
    need = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    missing, left, best = len(t), 0, (0, 10 ** 9)
    for right, ch in enumerate(s):
        if need.get(ch, 0) > 0:
            missing -= 1
        need[ch] = need.get(ch, 0) - 1
        if missing == 0:
            while need[s[left]] < 0:
                need[s[left]] += 1
                left += 1
            if right + 1 - left < best[1] - best[0]:
                best = (left, right + 1)
            need[s[left]] += 1
            missing += 1
            left += 1
    return '' if best[1] == 10 ** 9 else s[best[0]:best[1]]
```

