from collections import OrderedDict

def lru_simulate(capacity, operations):
    cache = OrderedDict()
    res = []
    for op in operations:
        if op[0] == 'get':
            if op[1] in cache:
                cache.move_to_end(op[1])
                res.append(cache[op[1]])
            else:
                res.append(-1)
        else:
            cache[op[1]] = op[2]
            cache.move_to_end(op[1])
            if len(cache) > capacity:
                cache.popitem(last=False)
    return res
